import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.B2FZg54p.js";const s="/heidrun/experiments/web-doc-by-ai/documentation_images/tabs/tabs_annotated.svg",m=JSON.parse('{"title":"Create, select and rename tabs","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/tabs.md","filePath":"documentation/tabs.md"}'),n={name:"documentation/tabs.md"};function i(l,e,h,c,d,b){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="create-select-and-rename-tabs" tabindex="-1">Create, select and rename tabs <a class="header-anchor" href="#create-select-and-rename-tabs" aria-label="Permalink to &quot;Create, select and rename tabs&quot;">​</a></h1><p>Create a tab in the selected workspace, switch between tabs, and give a tab a name.</p><h2 id="where-tabs-appear" tabindex="-1">Where tabs appear <a class="header-anchor" href="#where-tabs-appear" aria-label="Permalink to &quot;Where tabs appear&quot;">​</a></h2><p>The tab bar is at the top of the viewport and shows the tabs in the selected workspace. Each tab holds one or more panes.</p><p><img src="'+s+'" alt="The tab bar and selected tab, with the command bar above them"></p><h2 id="create-a-tab" tabindex="-1">Create a tab <a class="header-anchor" href="#create-a-tab" aria-label="Permalink to &quot;Create a tab&quot;">​</a></h2><p>Choose the command before creating a tab. The setting applies to tabs you create later.</p><ol><li>Click <strong>More actions</strong> at the upper right of the window, then select <strong>Settings</strong>.</li><li>In the Settings window, select <strong>New tab</strong>.</li><li>Under <strong>Default command of a new tab</strong>, choose <strong>Terminal</strong>, <strong>Claude Code</strong>, or <strong>Codex</strong>. Choose <strong>Terminal</strong> to start a shell.</li><li>Close the Settings window with its <strong>Close (Escape)</strong> button or by pressing <strong>Escape</strong>.</li><li>Click the <strong>+</strong> button at the end of the tab bar, or press <strong>⌘T</strong>. Heidrun creates a tab and starts the command you selected.</li></ol><p>To start the previous pane again, hold <strong>Shift</strong> while clicking <strong>+</strong>. If there is no previous pane, Heidrun starts the default command.</p><h2 id="select-a-tab" tabindex="-1">Select a tab <a class="header-anchor" href="#select-a-tab" aria-label="Permalink to &quot;Select a tab&quot;">​</a></h2><p>Click a tab to select it and show its panes. Press <strong>⌥⌘←</strong> to select the previous tab, or <strong>⌥⌘→</strong> to select the next tab.</p><h2 id="rename-a-tab" tabindex="-1">Rename a tab <a class="header-anchor" href="#rename-a-tab" aria-label="Permalink to &quot;Rename a tab&quot;">​</a></h2><ol><li>Double-click the tab name. The name field opens with the current name selected.</li><li>Enter the new name.</li><li>Press <strong>Enter</strong> or leave the field to save the name.</li></ol><p>While the name field is still open, press <strong>Escape</strong> to cancel and keep the existing name.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to look up other keyboard commands.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/pane_focus_history.html">Return to a previously focused pane</a>: to return to a pane you used earlier.</li></ul>',16)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
